cyBboxPatch(xy, w, h, boxstyle=\"round,pad=0.12\",\n                         facecolor=fill, edgecolor=edge, linewidth=lw,\n                         zorder=zorder, mutation_scale=0.5)\n    # subtle shadow\n    shadow = FancyBboxPatch((xy[0]+0.04, xy[1]-0.04), w, h,\n                            boxstyle=\"round,pad=0.12\",\n                            facecolor='#00000008', edgecolor='none',\n                            zorder=zorder-1, mutation_scale=0.5)\n    ax.add_patch(shadow)\n    ax.add_patch(box)\n    return box\n\ndef arrow(ax, x1, y1, x2, y2, color=C['gray_text'], lw=1.2, style='->', zorder=4, ls='-'):\n    ax.annotate('', xy=(x2, y2), xytext=(x1, y1),\n                arrowprops=dict(arrowstyle=style, color=color, lw=lw,\n                               linestyle=ls, shrinkA=0, shrinkB=0),\n                zorder=zorder)\n\n# Panel label\nax.text(0.15, 9.7, '(a)', fontsize=13, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='top')\nax.text(3.8, 9.7, 'ACR-VLA Pipeline', fontsize=12, fontweight='bold',\n        fontfamily='serif', color=C['navy'], va='top', ha='center')\n\n# ── Component positions (y centered around 5.0) ──\ncy = 4.8  # center y for main pipeline\n\n# 1. Observation box\nobs_x, obs_w, obs_h = 0.2, 1.1, 1.0\nadd_rounded_box(ax, (obs_x, cy - obs_h/2), obs_w, obs_h,\n                C['gray_light'], C['gray_border'])\nax.text(obs_x + obs_w/2, cy + 0.08, '📷', fontsize=10, ha='center', va='center', zorder=5)\nax.text(obs_x + obs_w/2, cy - 0.28, 'Obs', fontsize=8, ha='center', va='center',\n        fontfamily='sans-serif', color=C['navy'], zorder=5)\n\n# 2. Arrow obs → VLA\narrow(ax, obs_x + obs_w + 0.05, cy, 1.65, cy)\n\n# 3. Frozen VLA box\nvla_x, vla_w, vla_h = 1.7, 1.7, 1.8\nadd_rounded_box(ax, (vla_x, cy - vla_h/2), vla_w, vla_h,\n                C['steel'], C['navy'], lw=1.8)\nax.text(vla_x + vla_w/2, cy + 0.45, 'Frozen VLA', fontsize=9.5, fontweight='bold',\n        fontfamily='serif', color=C['navy'], ha='center', va='center', zorder=5)\nax.text(vla_x + vla_w/2, cy + 0.05, '❄', fontsize=8, ha='center', va='center', zorder=5)\nax.text(vla_x + vla_w/2, cy - 0.35, '0.4–3.6B params', fontsize=6.5,\n        fontfamily='sans-serif', color=C['gray_text'], ha='center', va='center', zorder=5)\nax.text(vla_x + vla_w/2, cy - vla_h/2 - 0.2, 'NO gradient', fontsize=6.5,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='top', zorder=5)\n\n# 4. K=2 sampling region\nk_x = vla_x + vla_w + 0.45\nk_bw, k_bh = 0.55, 0.45\n# Dashed arrows from VLA to samples\narrow(ax, vla_x + vla_w + 0.05, cy + 0.25, k_x - 0.05, cy + 0.55,\n      ls='--', style='->', color=C['gray_text'], lw=0.8)\narrow(ax, vla_x + vla_w + 0.05, cy - 0.25, k_x - 0.05, cy - 0.55 + k_bh,\n      ls='--', style='->', color=C['gray_text'], lw=0.8)\n\n# a1 box\nadd_rounded_box(ax, (k_x, cy + 0.25), k_bw, k_bh, C['coral'], '#E8A0A0', lw=0.8)\nax.text(k_x + k_bw/2, cy + 0.25 + k_bh/2, '$a_1$', fontsize=8.5, ha='center', va='center',\n        fontfamily='serif', color=C['red'], zorder=5)\n\n# a2 box\nadd_rounded_box(ax, (k_x, cy - 0.7), k_bw, k_bh, C['green_fill'], '#A0D0A0', lw=0.8)\nax.text(k_x + k_bw/2, cy - 0.7 + k_bh/2, '$a_2$', fontsize=8.5, ha='center', va='center',\n        fontfamily='serif', color=C['green'], zorder=5)\n\n# K=2 label\nax.text(k_x + k_bw/2, cy + 0.25 + k_bh + 0.15, '$K$=2', fontsize=6.5,\n        color=C['gray_text'], ha='center', va='bottom', fontfamily='sans-serif', zorder=5)\n\n# 5. Arrows samples → Argmin\nargmin_x = k_x + k_bw + 0.45\narrow(ax, k_x + k_bw + 0.05, cy + 0.25 + k_bh/2, argmin_x - 0.05, cy + 0.1,\n      ls='--', color=C['gray_text'], lw=0.8)\narrow(ax, k_x + k_bw + 0.05, cy - 0.7 + k_bh/2, argmin_x - 0.05, cy - 0.1,\n      ls='--', color=C['gray_text'], lw=0.8)\n\n# Argmin box\nargmin_w, argmin_h = 1.4, 1.1\nadd_rounded_box(ax, (argmin_x, cy - argmin_h/2), argmin_w, argmin_h,\n                C['yellow'], C['yellow_border'])\nax.text(argmin_x + argmin_w/2, cy + 0.18, 'Argmin', fonts