ottom to CRM bottom\nfrom matplotlib.patches import Arc\narc_y = cy - vla_h/2 - 0.6\nvla_cx = vla_x + vla_w/2\ncrm_cx = crm_x + crm_w/2\nmid_x = (vla_cx + crm_cx) / 2\n\n# Draw curved dashed arrow for obs features\nstyle_str = \"arc3,rad=0.4\"\nax.annotate('', xy=(crm_cx, cy - crm_h/2 - 0.05),\n            xytext=(vla_cx, cy - vla_h/2 - 0.05),\n            arrowprops=dict(arrowstyle='->', color=C['gray_text'],\n                           lw=0.8, linestyle='--',\n                           connectionstyle=style_str),\n            zorder=2)\nax.text(mid_x, cy - vla_h/2 - 0.95, 'obs features', fontsize=6.5,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='top', zorder=5)\n\n# ══════════════════════════════════════════════════════\n# Panel (b) — Adaptive Gating\n# ══════════════════════════════════════════════════════\nax = ax_b\nax.set_xlim(0, 10)\nax.set_ylim(0, 10)\n\n# Panel label\nax.text(0.2, 9.8, '(b)', fontsize=13, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='top')\nax.text(5.0, 9.8, 'Adaptive Gating', fontsize=11, fontweight='bold',\n        fontfamily='serif', color=C['navy'], va='top', ha='center')\n\n# Diamond for L2 distance\ndiamond_cx, diamond_cy = 5.0, 7.2\ndiamond_r = 1.2\ndiamond = plt.Polygon([\n    (diamond_cx, diamond_cy + diamond_r),\n    (diamond_cx + diamond_r * 1.2, diamond_cy),\n    (diamond_cx, diamond_cy - diamond_r),\n    (diamond_cx - diamond_r * 1.2, diamond_cy)\n], closed=True, facecolor='#FAFAFA', edgecolor=C['navy'], linewidth=1.5, zorder=3)\nax.add_patch(diamond)\nax.text(diamond_cx, diamond_cy + 0.2, 'L2 dist', fontsize=8.5, ha='center', va='center',\n        fontfamily='sans-serif', color=C['navy'], zorder=5)\nax.text(diamond_cx, diamond_cy - 0.35, r'$d=\\|a_1-a_2\\|_2$', fontsize=7,\n        fontstyle='italic', fontfamily='serif', color=C['gray_text'],\n        ha='center', va='center', zorder=5)\n\n# LEFT branch: d > τ → VLA Uncertain\nleft_cx, left_cy = 2.5, 3.2\narrow(ax, diamond_cx - di