)"," ","+"," # ══════════════════════════════════════════════════════","-# Panel (c) — Gating Effect scatter plot","+# Panel (c) — Gating Effect"," # ══════════════════════════════════════════════════════"," ax = ax_c"," ","-# Data"," suites = {","     'Spatial': (7.8, 2.1, C['navy']),","     'Goal':    (5.2, 1.3, C['blue']),"]},{"oldStart":279,"oldLines":64,"newStart":253,"newLines":55,"lines":[" ax.set_ylim(-1.3, 3.3)"," ax.set_facecolor(C['bg'])"," ","-# Clean spines","-for spine in ['top', 'right']:","-    ax.spines[spine].set_visible(False)","-for spine in ['left', 'bottom']:","-    ax.spines[spine].set_color(C['spine'])","-    ax.spines[spine].set_linewidth(0.8)","+for s in ['top', 'right']:","+    ax.spines[s].set_visible(False)","+for s in ['left', 'bottom']:","+    ax.spines[s].set_color(C['spine'])","+    ax.spines[s].set_linewidth(0.8)"," ","-# Grid"," ax.yaxis.grid(True, color=C['grid'], linewidth=0.5, zorder=0)"," ax.xaxis.grid(False)","-","-# Ticks"," ax.set_xticks([2, 3, 4, 5, 6, 7, 8, 9])"," ax.set_yticks([-1.0, 0.0, 1.0, 2.0, 3.0])"," ax.tick_params(axis='both', labelsize=7, colors=C['gray_text'], length=3, width=0.6)"," ","-# Labels","-ax.set_xlabel('Trigger Rate (%)', fontsize=8, fontfamily='serif', color=C['navy'],","-              labelpad=3)","-ax.set_ylabel('Δ SR (pp)', fontsize=8, fontfamily='serif', color=C['navy'],","-              labelpad=3)","+ax.set_xlabel('Trigger Rate (%)', fontsize=8.5, fontfamily='serif', color=C['navy'], labelpad=4)","+ax.set_ylabel('Δ SR (pp)', fontsize=8.5, fontfamily='serif', color=C['navy'], labelpad=4)"," "," # Title","-ax.text(0.5, 1.02, 'Gating Modulates Intervention', fontsize=9, fontweight='bold',","+ax.text(0.5, 1.04, 'Gating Modulates Intervention', fontsize=10, fontweight='bold',","         fontfamily='serif', color=C['navy'], ha='center', va='bottom',","         transform=ax.transAxes)","-","-# Panel label","-ax.text(-0.08, 1.02, '(c)', fontsize=13, fontweight='bold', fontfamily='serif',","+ax.text(-0.12, 1.04, '(c)', fontsize=14, fontweight='bold', fontfamily='serif',","         color=C['navy'], va='bottom', transform=ax.transAxes)"," ","-# Vertical dashed line at x=5.0","-ax.axvline(x=5.0, color=C['spine'], linewidth=0.8, linestyle='--', zorder=1)","-ax.text(3.5, 3.05, 'Confident', fontsize=6.5, fontstyle='italic', color=C['gray_text'],","+# Vertical dashed line at x=5","+ax.axvline(x=5.0, color=C['spine'], linewidth=0.8, linestyle='--', zorder=1, alpha=0.6)","+ax.text(3.3, 3.1, 'Confident', fontsize=7, fontstyle='italic', color=C['gray_text'],","         ha='center', va='bottom')","-ax.text(7.0, 3.05, 'Uncertain', fontsize=6.5, fontstyle='italic', color=C['gray_text'],","+ax.text(7.2, 3.1, 'Uncertain', fontsize=7, fontstyle='italic', color=C['gray_text'],","         ha='center', va='bottom')"," ","-# Plot data points","-label_offsets = {","-    'Spatial': (0.35, 0.15),","-    'Goal': (0.35, 0.1),","-    'Object': (0.35, 0.15),","-    'Long': (0.35, -0.15),","+# Zero line","+ax.axhline(y=0, color=C['spine'], linewidth=0.4, zorder=1, alpha=0.4)","+","+# Data points","+offsets = {","+    'Spatial': (0.4, 0.0),","+    'Goal':    (0.4, 0.05),","+    'Object':  (-0.2, 0.3),","+    'Long':    (-0.15, -0.35),"," }"," "," for name, (x, y, color) in suites.items():","-    ax.scatter(x, y, s=140, facecolor='white', edgecolor=color, linewidth=2.0, zorder=5)","-    ox, oy = label_offsets[name]","-    ax.text(x + ox, y + oy, name, fontsize=7, color=color, fontweight='bold',","-            va='center', ha='left', zorder=5)","+    ax.scatter(x, y, s=160, facecolor='white', edgecolor=color, linewidth=2.2, zorder=5)","+    ox, oy = offsets[name]","+    ax.text(x + ox, y + oy, name, fontsize=7.5, color=color, fontweight='bold',","+            va='center', ha='left' if ox > 0 else 'right', zorder=5)"," ","-# Zero line","-ax.axhline(y=0, color=C['spine'], linewidth=0.4, zorder=1)","-","-plt.savefig('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/artifacts/figures/fig1_vA_dense.png',","-            dpi=300, bbox_inches='tight', pad_inches=0.05, facecolor=C['bg'])","-plt.savefig('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/artifacts/figures/fig1_vA_dense.pdf',","-            bbox_inches='tight', pad_inches=0.05, facecolor=C['bg'])","+# ── Save ──","+out = '/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/artifacts/figures/fig1_vA_dense'","+plt.savefig(f'{out}.png', dpi=300, bbox_inches='tight', pad_inches=0.05, facecolor=C['bg'])","+plt.savefig(f'{out}.pdf', bbox_inches='tight', pad_inches=0.05, facecolor=C['bg'])"," plt.close()"," print('PNG + PDF saved')"]}],"originalFile":"#!/usr/bin/env python3\n\"\"\"Generate ACR-VLA Figure 1 version A (information-dense) with matplotlib.\"\"\"\n\nimport matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\nimport matplotlib.patches as mpatches\nfrom matplotlib.patches import FancyBboxPatch, FancyArrowPatch\nimport matplotlib.patheffects as pe\nimport numpy as np\n\n# ── Colors ──\nC = {\n    'bg': '#FFFFFF',\n    'navy': '#2C3E50',\n    'steel': '#D6E4F0',\n    'gray_border': '#BDC3C7',\n    'gray_text': '#7F8C8D',\n    'gray_light': '#F5F6F7',\n    'yellow': '#FEF9E7',\n    'yellow_border': '#F39C12',\n    'orange_fill': '#FDEBD0',\n    'orange': '#E67E22',\n    'green_fill': '#D5F5E3',\n    'green': '#27AE60',\n    'coral': '#FADBD8',\n    'red': '#C0392B',\n    'blue': '#2980B9',\n    'grid': '#F0F0F0',\n    'spine': '#BDC3C7',\n}\n\nfig = plt.figure(figsize=(14, 4.8), dpi=300, facecolor=C['bg'])\n\n# Layout: panel (a) left 53%, panels (b)+(c) right 45%\n# Using gridspec for precise control\ngs = fig.add_gridspec(2, 2, width_ratios=[1.15, 0.85], height_ratios=[1, 1],\n                      wspace=0.06, hspace=0.15,\n                      left=0.02, right=0.98, top=0.94, bottom=0.04)\n\nax_a = fig.add_subplot(gs[:, 0])  # panel (a) spans both rows\nax_b = fig.add_subplot(gs[0, 1])  # panel (b) top-right\nax_c = fig.add_subplot(gs[1, 1])  # panel (c) bottom-right\n\nfor ax in [ax_a, ax_b]:\n    ax.set_xlim(0, 10)\n    ax.set_ylim(0, 10)\n    ax.set_aspect('equal')\n    ax.axis('off')\n\n# ══════════════════════════════════════════════════════\n# Panel (a) — ACR-VLA Pipeline\n# ══════════════════════════════════════════════════════\nax = ax_a\n\ndef add_rounded_box(ax, xy, w, h, fill, edge, lw=1.2, zorder=3):\n    box = FancyBboxPatch(xy, w, h, boxstyle=\"round,pad=0.12\",\n                         facecolor=fill, edgecolor=edge, linewidth=lw,\n                         zorder=zorder, mutation_scale=0.5)\n    # subtle shadow\n    shadow = FancyBboxPatch((xy[0]+0.04, xy[1]-0.04), w, h,\n                            boxstyle=\"round,pad=0.12\",\n                            facecolor='#00000008', edgecolor='none',\n                            zorder=zorder-1, mutation_scale=0.5)\n    ax.add_patch(shadow)\n    ax.add_patch(box)\n    return box\n\ndef arrow(ax, x1, y1, x2, y2, color=C['gray_text'], lw=1.2, style='->', zorder=4, ls='-'):\n    ax.annotate('', xy=(x2, y2), xytext=(x1, y1),\n                arrowprops=dict(arrowstyle=style, color=color, lw=lw,\n                               linestyle=ls, shrinkA=0, shrinkB=0),\n                zorder=zorder)\n\n# Panel label\nax.text(0.15, 9.7, '(a)', fontsize=13, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='top')\nax.text(3.8, 9.7, 'ACR-VLA Pipeline', fontsize=12, fontweight='bold',\n        fontfamily='serif', color=C['navy'], va='top', ha='center')\n\n# ── Component positions (y centered around 5.0) ──\ncy = 4.8  # center y for main pipeline\n\n# 1. Observation box\nobs_x, obs_w, obs_h = 0.2, 1.1, 1.0\nadd_rounded_box(ax, (obs_x, cy - obs_h/2), obs_w, obs_h,\n                C['gray_light'], C['gray_border'])\nax.text(obs_x + obs_w/2, cy + 0.08, '📷', fontsize=10, ha='center', va='center', zorder=5)\nax.text(obs_x + obs_w/2, cy - 0.28, 'Obs', fontsize=8, ha='center', va='center',\n        fontfamily='sans-serif', color=C['navy'], zorder=5)\n\n# 2. Arrow obs → VLA\narrow(ax, obs_x + obs_w + 0.05, cy, 1.65, cy)\n\n# 3. Frozen VLA box\nvla_x, vla_w, vla_h = 1.7, 1.7, 1.8\nadd_rounded_box(ax, (vla_x, cy - vla_h/2), vla_w, vla_h,\n                C['steel'], C['navy'], lw=1.8)\nax.text(vla_x + vla_w/2, cy + 0.45, 'Frozen VLA', fontsize=9.5, fontweight='bold',\n        fontfamily='serif', color=C['navy'], ha='center', va='center', zorder=5)\nax.text(vla_x + vla_w/2, cy + 0.05, '❄', fontsize=8, ha='center', va='center', zorder=5)\nax.text(vla_x + vla_w/2, cy - 0.35, '0.4–3.6B params', fontsize=6.5,\n        fontfamily='sans-serif', color=C['gray_text'], ha='center', va='center', zorder=5)\nax.text(vla_x + vla_w/2, cy - vla_h/2 - 0.2, 'NO gradient', fontsize=6.5,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='top', zorder=5)\n\n# 4. K=2 sampling region\nk_x = vla_x + vla_w + 0.45\nk_bw, k_bh = 0.55, 0.45\n# Dashed arrows from VLA to samples\narrow(ax, vla_x + vla_w + 0.05, cy + 0.25, k_x - 0.05, cy + 0.55,\n      ls='--', style='->', color=C['gray_text'], lw=0.8)\narrow(ax, vla_x + vla_w + 0.05, cy - 0.25, k_x - 0.05, cy - 0.55 + k_bh,\n      ls='--', style='->', color=C['gray_text'], lw=0.8)\n\n# a1 box\nadd_rounded_box(ax, (k_x, cy + 0.25), k_bw, k_bh, C['coral'], '#E8A0A0', lw=0.8)\nax.text(k_x + k_bw/2, cy + 0.25 + k_bh/2, '$a_1$', fontsize=8.5, ha='center', va='center',\n        fontfamily='serif', color=C['red'], zorder=5)\n\n# a2 box\nadd_rounded_box(ax, (k_x, cy - 0.7), k_bw, k_bh, C['green_fill'], '#A0D0A0', lw=0.8)\nax.text(k_x + k_bw/2, cy - 0.7 + k_bh/2, '$a_2$', fontsize=8.5, ha='center', va='center',\n        fontfamily='serif', color=C['green'], zorder=5)\n\n# K=2 label\nax.text(k_x + k_bw/2, cy + 0.25 + k_bh + 0.15, '$K$=2', fontsize=6.5,\n        color=C['gray_text'], ha='center', va='bottom', fontfamily='sans-serif', zorder=5)\n\n# 5. Arrows samples → Argmin\nargmin_x = k_x + k_bw + 0.45\narrow(ax, k_x + k_bw + 0.05, cy + 0.25 + k_bh/2, argmin_x - 0.05, cy + 0.1,\n      ls='--', color=C['gray_text'], lw=0.8)\narrow(ax, k_x + k_bw + 0.05, cy - 0.7 + k_bh/2, argmin_x - 0.05, cy - 0.1,\n      ls='--', color=C['gray_text'], lw=0.8)\n\n# Argmin box\nargmin_w, argmin_h = 1.4, 1.1\nadd_rounded_box(ax, (argmin_x, cy - argmin_h/2), argmin_w, argmin_h,\n                C['yellow'], C['yellow_border'])\nax.text(argmin_x + argmin_w/2, cy + 0.18, 'Argmin', fontsize=9, fontweight='bold',\n        fontfamily='serif', color='#B8860B', ha='center', va='center', zorder=5)\nax.text(argmin_x + argmin_w/2, cy - 0.18, r'$\\arg\\min_i \\|a_i - \\bar{a}\\|$',\n        fontsize=6.5, fontstyle='italic', color=C['gray_text'],\n        ha='center', va='center', zorder=5)\n\n# 6. Arrow Argmin → CRM\ncrm_x = argmin_x + argmin_w + 0.35\narrow(ax, argmin_x + argmin_w + 0.05, cy, crm_x - 0.05, cy)\n\n# 7. CRM box\ncrm_w, crm_h = 1.2, 1.3\nadd_rounded_box(ax, (crm_x, cy - crm_h/2), crm_w, crm_h,\n                C['orange_fill'], C['orange'], lw=1.8)\nax.text(crm_x + crm_w/2, cy + 0.28, 'CRM', fontsize=10, fontweight='bold',\n        fontfamily='serif', color=C['orange'], ha='center', va='center', zorder=5)\nax.text(crm_x + crm_w/2, cy - 0.05, '615K params', fontsize=6, color=C['gray_text'],\n        ha='center', va='center', fontfamily='sans-serif', zorder=5)\nax.text(crm_x + crm_w/2, cy - 0.30, '1.8 MB', fontsize=6, color=C['gray_text'],\n        ha='center', va='center', fontfamily='sans-serif', zorder=5)\n\n# 8. Arrow CRM → Refined Action with δ_a\nref_x = crm_x + crm_w + 0.6\narrow(ax, crm_x + crm_w + 0.05, cy, ref_x - 0.05, cy)\nax.text(crm_x + crm_w + 0.32, cy + 0.22, '$+\\\\delta_a$', fontsize=7,\n        color=C['gray_text'], ha='center', va='bottom', zorder=5)\n\n# 9. Refined Action box\nref_w, ref_h = 1.2, 0.9\nadd_rounded_box(ax, (ref_x, cy - ref_h/2), ref_w, ref_h,\n                C['green_fill'], C['green'], lw=1.5)\nax.text(ref_x + ref_w/2, cy + 0.05, 'Refined', fontsize=8, fontfamily='serif',\n        color=C['green'], ha='center', va='center', zorder=5, fontweight='bold')\nax.text(ref_x + ref_w/2, cy - 0.2, 'Action', fontsize=8, fontfamily='serif',\n        color=C['green'], ha='center', va='center', zorder=5, fontweight='bold')\n\n# obs features dashed arc from VLA bottom to CRM bottom\nfrom matplotlib.patches import Arc\narc_y = cy - vla_h/2 - 0.6\nvla_cx = vla_x + vla_w/2\ncrm_cx = crm_x + crm_w/2\nmid_x = (vla_cx + crm_cx) / 2\n\n# Draw curved dashed arrow for obs features\nstyle_str = \"arc3,rad=0.4\"\nax.annotate('', xy=(crm_cx, cy - crm_h/2 - 0.05),\n            xytext=(vla_cx, cy - vla_h/2 - 0.05),\n            arrowprops=dict(arrowstyle='->', color=C['gray_text'],\n                           lw=0.8, linestyle='--',\n                           connectionstyle=style_str),\n            zorder=2)\nax.text(mid_x, cy - vla_h/2 - 0.95, 'obs features', fontsize=6.5,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='top', zorder=5)\n\n# ══════════════════════════════════════════════════════\n# Panel (b) — Adaptive Gating\n# ══════════════════════════════════════════════════════\nax = ax_b\nax.set_xlim(0, 10)\nax.set_ylim(0, 10)\n\n# Panel label\nax.text(0.2, 9.8, '(b)', fontsize=13, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='top')\nax.text(5.0, 9.8, 'Adaptive Gating', fontsize=11, fontweight='bold',\n        fontfamily='serif', color=C['navy'], va='top', ha='center')\n\n# Diamond for L2 distance\ndiamond_cx, diamond_cy = 5.0, 7.2\ndiamond_r = 1.2\ndiamond = plt.Polygon([\n    (diamond_cx, diamond_cy + diamond_r),\n    (diamond_cx + diamond_r * 1.2, diamond_cy),\n    (diamond_cx, diamond_cy - diamond_r),\n    (diamond_cx - diamond_r * 1.2, diamond_cy)\n], closed=True, facecolor='#FAFAFA', edgecolor=C['navy'], linewidth=1.5, zorder=3)\nax.add_patch(diamond)\nax.text(diamond_cx, diamond_cy + 0.2, 'L2 dist', fontsize=8.5, ha='center', va='center',\n        fontfamily='sans-serif', color=C['navy'], 