                      facecolor='#00000008', edgecolor='none', zorder=zorder-1)\n    ax.add_patch(shadow)\n    ax.add_patch(box)\n\ndef draw_arrow(ax, x1, y1, x2, y2, color=None, lw=1.2, ls='-'):\n    if color is None:\n        color = C['gray_text']\n    ax.annotate('', xy=(x2, y2), xytext=(x1, y1),\n                arrowprops=dict(arrowstyle='->,head_width=0.15,head_length=0.2',\n                               color=color, lw=lw, linestyle=ls), zorder=4)\n\n\n# ══════════════════════════════════════════════════════\n# Panel (a) — ACR-VLA Pipeline\n# ══════════════════════════════════════════════════════\nax = ax_a\nax.set_xlim(-1, 21)\nax.set_ylim(-3.5, 7.5)\nax.axis('off')\n\nax.text(-0.5, 7.0, '(a)', fontsize=14, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='top')\nax.text(8.5, 7.0, 'ACR-VLA Pipeline', fontsize=13, fontweight='bold',\n        fontfamily='serif', color=C['navy'], va='top', ha='center')\n\ncy = 2.8\n\n# 1. Obs\nobs_cx = 0.8\ndraw_box(ax, obs_cx, cy, 1.6, 1.6, C['gray_light'], C['gray_border'])\n# Camera icon via simple shapes\nax.plot([obs_cx-0.3, obs_cx+0.3, obs_cx+0.3, obs_cx-0.3, obs_cx-0.3],\n        [cy+0.35, cy+0.35, cy-0.05, cy-0.05, cy+0.35],\n        color=C['gray_text'], lw=0.8, zorder=5)\nax.plot([obs_cx-0.1, obs_cx+0.1], [cy+0.45, cy+0.45],\n        color=C['gray_text'], lw=0.8, zorder=5)\nax.add_patch(plt.Circle((obs_cx, cy+0.15), 0.12, fill=False,\n             edgecolor=C['gray_text'], lw=0.6, zorder=5))\nax.text(obs_cx, cy - 0.45, 'Obs', fontsize=9.5, ha='center', va='center',\n        fontfamily='sans-serif', color=C['navy'], zorder=5, fontweight='bold')\n\n# Arrow Obs → VLA\ndraw_arrow(ax, obs_cx + 0.85, cy, 2.65, cy)\n\n# 2. Frozen VLA\nvla_cx = 4.3\ndraw_box(ax, vla_cx, cy, 2.8, 2.8, C['steel'], C['navy'], lw=1.8)\nax.text(vla_cx, cy + 0.75, 'Frozen VLA', fontsize=11, fontweight='bold',\n        fontfamily='serif', color=C['navy'], ha='center', va='center', zorder=5)\n# Snowflake via simple * with nice styling\nax.text(vla_cx + 1.0, cy + 0.75, '*', fontsize=14, ha='center', va='center',\n        color='#5B9BD5', zorder=5, fontweight='bold',\n        path_effects=[pe.withStroke(linewidth=0.3, foreground='#5B9BD5')])\nax.text(vla_cx, cy + 0.05, '0.4 – 3.6B params', fontsize=7.5,\n        fontfamily='sans-serif', color=C['gray_text'], ha='center', va='center', zorder=5)\n# Lock icon (simple rectangle + arc)\nlock_x, lock_y = vla_cx, cy - 0.55\nax.add_patch(FancyBboxPatch((lock_x-0.15, lock_y-0.15), 0.3, 0.22,\n             boxstyle=\"round,pad=0.02\", facecolor=C['navy'], edgecolor=C['navy'],\n             linewidth=0.5, zorder=5))\nax.add_patch(plt.matplotlib.patches.Arc((lock_x, lock_y+0.07), 0.2, 0.2,\n             angle=0, theta1=0, theta2=180, edgecolor=C['navy'], lw=0.8, zorder=5))\nax.text(vla_cx, cy - 1.8, 'NO gradient', fontsize=7.5,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='top', zorder=5)\n\n# 3. K=2 samples\nk_cx = 7.2\nk_top_y = cy + 1.0\nk_bot_y = cy - 1.0\ndraw_arrow(ax, 5.75, cy + 0.3, k_cx - 0.55, k_top_y, ls='--', lw=0.9)\ndraw_arrow(ax, 5.75, cy - 0.3, k_cx - 0.55, k_bot_y, ls='--', lw=0.9)\n\ndraw_box(ax, k_cx, k_top_y, 0.9, 0.75, C['coral'], '#D4A0A0', lw=0.8)\nax.text(k_cx, k_top_y, r'$a_1$', fontsize=10.5, ha='center', va='center',\n        color='#A93226', zorder=5)\n\ndraw_box(ax, k_cx, k_bot_y, 0.9, 0.75, C['green_fill'], '#82C99A', lw=0.8)\nax.text(k_cx, k_bot_y, r'$a_2$', fontsize=10.5, ha='center', va='center',\n        color='#1E8449', zorder=5)\n\nax.text(k_cx, cy + 1.7, r'$K\\!=\\!2$', fontsize=8,\n        color=C['gray_text'], ha='center', va='bottom', zorder=5)\nax.text(k_cx + 0.7, cy, 'samples', fontsize=7,\n        color=C['gray_text'], ha='left', va='center', zorder=5)\n\n# 4. Arrows samples → Argmin\nargmin_cx = 10.0\ndraw_arrow(ax, k_cx + 0.5, k_top_y, argmin_cx - 1.05, cy + 0.15, ls='--', lw=0.9)\ndraw_arrow(ax, k_cx + 0.5, k_bot_y, argmin_cx - 1.05, cy - 0.15, ls='--', lw=0.9)\n\n# Argmin box\ndraw_box(ax, argmin_cx, cy, 2.0, 1.8, C['yellow'], C['yellow_border'])\nax.text(argmin_cx, cy + 0.4, 'Argmin', fontsize=10.5, fontweight='bold',\n        fontfamily='serif', color='#9A7D0A', ha='center', va='center', zorder=5)\nax.text(argmin_cx, cy - 0.25, r'$\\arg\\min_i \\|a_i\\!-\\!\\bar{a}\\|$',\n        fontsize=7.5, color=C['gray_text'], ha='center', va='center', zorder=5)\n\n# 5. Arrow Argmin → CRM\ncrm_cx = 13.2\ndraw_arrow(ax, argmin_cx + 1.05, cy, crm_cx - 1.0, cy)\n\n# CRM box\ndraw_box(ax, crm_cx, cy, 1.9, 2.0, C['orange_fill'], C['orange'], lw=1.8)\nax.text(crm_cx, cy + 0.55, 'CRM', fontsize=12, fontweight='bold',\n        fontfamily='serif', color=C['orange'], ha='center', va='center', zorder=5)\nax.text(crm_cx, cy + 0.0, '615K params', fontsize=7, color=C['gray_text'],\n        ha='center', va='center', fontfamily='sans-serif', zorder=5)\nax.text(crm_cx, cy - 0.4, '1.8 MB', fontsize=7, color=C['gray_text'],\n        ha='center', va='center', fontfamily='sans-serif', zorder=5)\n\n# 6. Arrow CRM → Refined Action\nref_cx = 16.5\ndraw_arrow(ax, crm_cx + 1.0, cy, ref_cx - 1.0, cy)\nax.text((crm_cx + ref_cx) / 2, cy + 0.35, r'$+\\;\\delta_a$', fontsize=8.5,\n        color=C['gray_text'], ha='center', va='bottom', zorder=5)\n\n# Refined Action box\ndraw_box(ax, ref_cx, cy, 1.9, 1.5, C['green_fill'], C['green'], lw=1.5)\nax.text(ref_cx, cy + 0.2, 'Refined', fontsize=9.5, fontfamily='serif',\n        color='#1E8449', ha='center', va='center', zorder=5, fontweight='bold')\nax.text(ref_cx, cy - 0.25, 'Action', fontsize=9.5, fontfamily='serif',\n        color='#1E8449', ha='center', va='center', zorder=5, fontweight='bold')\n\n# obs features arc\nax.annotate('', xy=(crm_cx, cy - 1.05),\n            xytext=(vla_cx, cy - 1.45),\n            arrowprops=dict(arrowstyle='->,head_width=0.12,head_length=0.18',\n                           color=C['gray_text'], lw=0.8, linestyle='--',\n                           connectionstyle='arc3,rad=0.35'), zorder=2)\nax.text((vla_cx + crm_cx) / 2, cy - 2.5, 'obs features', fontsize=7.5,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='top', zorder=5)\n\n\n# ══════════════════════════════════════════════════════\n# Panel (b) — Adaptive Gating\n# ══════════════════════════════════════════════════════\nax = ax_b\nax.set_xlim(0, 10)\nax.set_ylim(-0.5, 10.5)\nax.axis('off')\n\nax.text(0.15, 10.0, '(b)', fontsize=14, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='top')\nax.text(5.0, 10.0, 'Adaptive Gating', fontsize=12, fontweight='bold',\n        fontfamily='serif', color=C['navy'], va='top', ha='center')\n\n# Diamond\nd_cx, d_cy = 5.0, 7.3\nd_ry, d_rx = 1.2, 1.5\ndiamond = Polygon([\n    (d_cx, d_cy + d_ry),\n    (d_cx + d_rx, d_cy),\n    (d_cx, d_cy - d_ry),\n    (d_cx - d_rx, d_cy)\n], closed=True, facecolor='#F8F9FA', edgecolor=C['navy'], linewidth=1.5, zorder=3)\nax.add_patch(diamond)\nax.text(d_cx, d_cy + 0.35, 'L2 dist', fontsize=9, ha='center', va='center',\n        fontfamily='sans-serif', color=C['navy'], zorder=5, fontweight='bold')\nax.text(d_cx, d_cy - 0.35, r'$d=\\|a_1\\!-\\!a_2\\|_2$', fontsize=7.5,\n        fontfamily='serif', color=C['gray_text'], ha='center', va='center', zorder=5)\n\n# LEFT: d > τ\nl_cx, l_cy = 2.3, 3.2\ndraw_arrow(ax, d_cx - d_rx - 0.05, d_cy - 0.4, l_cx + 1.4, l_cy + 1.1,\n           color=C['red'], lw=1.3)\nax.text(d_cx - d_rx - 0.3, d_cy + 0.3, r'$d\\!>\\!\\tau$', fontsize=10,\n        fontweight='bold', color=C['red'], ha='center', va='center', zorder=5)\n\ndraw_box(ax, l_cx + 1.0, l_cy + 0.3, 3.0, 1.7, C['coral'], C['red'], lw=1.2)\nax.text(l_cx + 1.0, l_cy + 0.75, 'VLA Uncertain', fontsize=9.5,\n        fontweight='bold', color=C['red'], ha='center', va='center', zorder=5)\nax.text(l_cx + 1.0, l_cy + 0.1, 'Apply CRM correction', fontsize=7.5,\n        color=C['gray_text'], ha='center', va='center', zorder=5)\n\n# RIGHT: d ≤ τ\nr_cx, r_cy = 6.7, 3.2\ndraw_arrow(ax, d_cx + d_rx + 0.05, d_cy - 0.4, r_cx, r_cy + 1.1,\n           color=C['green'], lw=1.3)\nax.text(d_cx + d_rx + 0.3, d_cy + 0.3, r'$d\\!\\leq\\!\\tau$', fontsize=10,\n        fontweight='bold', color=C['green'], ha='center', va='center', zorder=5)\n\ndraw_box(ax, r_cx + 0.5, r_cy + 0.3, 3.0, 1.7, C['green_fill'], C['green'], lw=1.2)\nax.text(r_cx + 0.5, r_cy + 0.75, 'VLA Confident', fontsize=9.5,\n        fontweight='bold', color=C['green'], ha='center', va='center', zorder=5)\nax.text(r_cx + 0.5, r_cy + 0.1, 'Use argmin directly', fontsize=7.5,\n        color=C['gray_text'], ha='center', va='center', zorder=5)\n\n# Exclamation and checkmark\nax.text(l_cx + 2.2, l_cy - 0.1, '!', fontsize=13, fontweight='bold',\n        color=C['red'], ha='center', va='center', zorder=5)\nax.text(r_cx + 1.7, r_cy - 0.1, u'✓', fontsize=13, fontweight='bold',\n        color=C['green'], ha='center', va='center', zorder=5)\n\n# tau annotation\nax.text(5.0, 1.0, r'$\\tau$ calibrated on held-out demos', fontsize=7.5,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='center')\n\n\n# ══════════════════════════════════════════════════════\n# Panel (c) — Gating Effect\n# ══════════════════════════════════════════════════════\nax = ax_c\n\nsuites = {\n    'Spatial': (7.8, 2.1, C['navy']),\n    'Goal':    (5.2, 1.3, C['blue']),\n    'Object':  (3.2, 0.1, C['orange']),\n    'Long':    (3.8, -0.3, C['red']),\n}\n\nax.set_xlim(1.5, 9.5)\nax.set_ylim(-1.3, 3.3)\nax.set_facecolor(C['bg'])\n\nfor s in ['top', 'right']:\n    ax.spines[s].set_visible(False)\nfor s in ['left', 'bottom']:\n    ax.spines[s].set_color(C['spine'])\n    ax.spines[s].set_linewidth(0.8)\n\nax.yaxis.grid(True, color=C['grid'], linewidth=0.5, zorder=0)\nax.set_xticks([2, 3, 4, 5, 6, 7, 8, 9])\nax.set_yticks([-1.0, 0.0, 1.0, 2.0, 3.0])\nax.tick_params(axis='both', labelsize=7.5, colors=C['gray_text'], length=3, width=0.6)\n\nax.set_xlabel('Trigger Rate (%)', fontsize=9, fontfamily='serif', color=C['navy'], labelpad=4)\nax.set_ylabel(r'$\\Delta$ SR (pp)', fontsize=9, fontfamily='serif', color=C['navy'], labelpad=4)\n\nax.text(0.5, 1.04, 'Gating Modulates Intervention', fontsize=10.5, fontweight='bold',\n        fontfamily='serif', color=C['navy'], ha='center', va='bottom',\n        transform=ax.transAxes)\nax.text(-0.12, 1.04, '(c)', fontsize=14, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='bottom', transform=ax.transAxes)\n\nax.axvline(x=5.0, color=C['spine'], linewidth=0.8, linestyle='--', zorder=1, alpha=0.5)\nax.text(3.2, 3.15, 'Confident', fontsize=7.5, fontstyle='italic', color=C['gray_text'],\n        ha='center', va='bottom')\nax.text(7.3, 3.15, 'Uncertain', fontsize=7.5, fontstyle='italic', color=C['gray_text'],\n        ha='center', va='bottom')\n\nax.axhline(y=0, color=C['spine'], linewidth=0.4, zorder=1, alpha=0.3)\n\noffsets = {\n    'Spatial': (0.45, 0.0),\n    'Goal':    (0.45, 0.0),\n    'Object':  (-0.15, 0.32),\n    'Long':    (-0.15, -0.35),\n}\n\nfor name, (x, y, color) in suites.items():\n    ax.scatter(x, y, s=180, facecolor='white', edgecolor=color, linewidth=2.2, zorder=5)\n    ox, oy = offsets[name]\n    ax.text(x + ox, y + oy, name, fontsize=8, color=color, fontweight='bold',\n            va='center', ha='left' if ox > 0 else 'right', zorder=5)\n\n\n# ── Save ──\nout = '/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/artifacts/figures/fig1_vA_dense'\nplt.savefig(f'{out}.png', dpi=300, bbox_inches='tight', pad_inches=0.05, facecolor=C['bg'])\nplt.savefig(f'{out}.pdf', bbox_inches='tight', pad_inches=0.05, facecolor=C['bg'])\nplt.close()\nprint('PNG + PDF saved')\n","structuredPatch":[{"oldStart":4,"oldLines":8,"newStart":4,"newLines":7,"lines":[" import matplotlib"," matplotlib.use('Agg')"," import matplotlib.pyplot as plt","-import matplotlib.patches as mpatches","-from matplotlib.patches import FancyBboxPatch","+from matplotlib.patches import FancyBboxPatch, FancyArrowPatch, Polygon"," import matplotlib.patheffects as pe"," import numpy as np"," "