e at x=5","-ax.axvline(x=5.0, color=C['spine'], linewidth=0.8, linestyle='--', zorder=1, alpha=0.6)","-ax.text(3.3, 3.1, 'Confident', fontsize=7, fontstyle='italic', color=C['gray_text'],","+ax.axvline(x=5.0, color=C['spine'], linewidth=0.8, linestyle='--', zorder=1, alpha=0.5)","+ax.text(3.2, 3.15, 'Confident', fontsize=7.5, fontstyle='italic', color=C['gray_text'],","         ha='center', va='bottom')","-ax.text(7.2, 3.1, 'Uncertain', fontsize=7, fontstyle='italic', color=C['gray_text'],","+ax.text(7.3, 3.15, 'Uncertain', fontsize=7.5, fontstyle='italic', color=C['gray_text'],","         ha='center', va='bottom')"," ","-# Zero line","-ax.axhline(y=0, color=C['spine'], linewidth=0.4, zorder=1, alpha=0.4)","+ax.axhline(y=0, color=C['spine'], linewidth=0.4, zorder=1, alpha=0.3)"," ","-# Data points"," offsets = {","-    'Spatial': (0.4, 0.0),","-    'Goal':    (0.4, 0.05),","-    'Object':  (-0.2, 0.3),","+    'Spatial': (0.45, 0.0),","+    'Goal':    (0.45, 0.0),","+    'Object':  (-0.15, 0.32),","     'Long':    (-0.15, -0.35),"," }"," "," for name, (x, y, color) in suites.items():","-    ax.scatter(x, y, s=160, facecolor='white', edgecolor=color, linewidth=2.2, zorder=5)","+    ax.scatter(x, y, s=180, facecolor='white', edgecolor=color, linewidth=2.2, zorder=5)","     ox, oy = offsets[name]","-    ax.text(x + ox, y + oy, name, fontsize=7.5, color=color, fontweight='bold',","+    ax.text(x + ox, y + oy, name, fontsize=8, color=color, fontweight='bold',","             va='center', ha='left' if ox > 0 else 'right', zorder=5)"," ","+"," # ── Save ──"," out = '/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/artifacts/figures/fig1_vA_dense'"," plt.savefig(f'{out}.png', dpi=300, bbox_inches='tight', pad_inches=0.05, facecolor=C['bg'])"]}],"originalFile":"#!/usr/bin/env python3\n\"\"\"Generate ACR-VLA Figure 1 version A (information-dense) with matplotlib.\"\"\"\n\nimport matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\nimport matplotlib.patches as mpatches\nfrom matplotlib.patches import FancyBboxPatch\nimport matplotlib.patheffects as pe\nimport numpy as np\n\n# ── Colors ──\nC = {\n    'bg': '#FFFFFF',\n    'navy': '#2C3E50',\n    'steel': '#D6E4F0',\n    'gray_border': '#BDC3C7',\n    'gray_text': '#7F8C8D',\n    'gray_light': '#F5F6F7',\n    'yellow': '#FEF9E7',\n    'yellow_border': '#F39C12',\n    'orange_fill': '#FDEBD0',\n    'orange': '#E67E22',\n    'green_fill': '#D5F5E3',\n    'green': '#27AE60',\n    'coral': '#FADBD8',\n    'red': '#C0392B',\n    'blue': '#2980B9',\n    'grid': '#F0F0F0',\n    'spine': '#BDC3C7',\n}\n\nfig = plt.figure(figsize=(14, 5.2), dpi=300, facecolor=C['bg'])\n\n# Layout: panel (a) left ~55%, panels (b)+(c) right ~42%\ngs = fig.add_gridspec(2, 2, width_ratios=[1.2, 0.8], height_ratios=[1, 1.05],\n                      wspace=0.08, hspace=0.25,\n                      left=0.02, right=0.98, top=0.95, bottom=0.06)\n\nax_a = fig.add_subplot(gs[:, 0])\nax_b = fig.add_subplot(gs[0, 1])\nax_c = fig.add_subplot(gs[1, 1])\n\n# ── Helpers ──\ndef draw_box(ax, cx, cy, w, h, fill, edge, lw=1.2, zorder=3):\n    \"\"\"Draw a rounded box centered at (cx, cy).\"\"\"\n    box = FancyBboxPatch((cx - w/2, cy - h/2), w, h,\n                         boxstyle=\"round,pad=0.08\",\n                         facecolor=fill, edgecolor=edge, linewidth=lw,\n                         zorder=zorder)\n    shadow = FancyBboxPatch((cx - w/2 + 0.15, cy - h/2 - 0.15), w, h,\n                            boxstyle=\"round,pad=0.08\",\n                            facecolor='#00000010', edgecolor='none',\n                            zorder=zorder-1)\n    ax.add_patch(shadow)\n    ax.add_patch(box)\n\ndef draw_arrow(ax, x1, y1, x2, y2, color=None, lw=1.2, ls='-', hw=0.15, hl=0.25):\n    if color is None:\n        color = C['gray_text']\n    ax.annotate('', xy=(x2, y2), xytext=(x1, y1),\n                arrowprops=dict(arrowstyle=f'->,head_width={hw},head_length={hl}',\n                               color=color, lw=lw, linestyle=ls),\n                zorder=4)\n\n\n# ══════════════════════════════════════════════════════\n# Panel (a) — ACR-VLA Pipeline\n# ══════════════════════════════════════════════════════\nax = ax_a\nax.set_xlim(-0.5, 20.5)\nax.set_ylim(-3, 7)\nax.axis('off')\n\n# Panel label + title\nax.text(-0.3, 6.5, '(a)', fontsize=14, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='top')\nax.text(8, 6.5, 'ACR-VLA Pipeline', fontsize=13, fontweight='bold',\n        fontfamily='serif', color=C['navy'], va='top', ha='center')\n\ncy = 2.5  # main pipeline center y\n\n# 1. Obs box\nobs_cx, obs_cy = 1.0, cy\ndraw_box(ax, obs_cx, obs_cy, 1.6, 1.5, C['gray_light'], C['gray_border'])\nax.text(obs_cx, obs_cy + 0.15, '⬜', fontsize=7, ha='center', va='center', zorder=5)\nax.text(obs_cx, obs_cy - 0.25, 'Obs', fontsize=9, ha='center', va='center',\n        fontfamily='sans-serif', color=C['navy'], zorder=5, fontweight='bold')\n\n# Arrow Obs → VLA\ndraw_arrow(ax, 1.85, cy, 2.75, cy)\n\n# 2. Frozen VLA box\nvla_cx = 4.3\ndraw_box(ax, vla_cx, cy, 2.8, 2.6, C['steel'], C['navy'], lw=1.8)\nax.text(vla_cx, cy + 0.65, 'Frozen VLA', fontsize=11, fontweight='bold',\n        fontfamily='serif', color=C['navy'], ha='center', va='center', zorder=5)\nax.text(vla_cx, cy + 0.05, '❄', fontsize=9, ha='center', va='center', zorder=5,\n        path_effects=[pe.withStroke(linewidth=0, foreground='white')])\nax.text(vla_cx, cy - 0.5, '0.4–3.6B params', fontsize=7,\n        fontfamily='sans-serif', color=C['gray_text'], ha='center', va='center', zorder=5)\nax.text(vla_cx, cy - 1.7, 'NO gradient', fontsize=7,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='top', zorder=5)\n\n# 3. K=2 sampling split\nk_cx = 7.0\nk_top_y = cy + 0.8\nk_bot_y = cy - 0.8\n\n# Dashed arrows VLA → a1, a2\ndraw_arrow(ax, 5.75, cy + 0.3, k_cx - 0.55, k_top_y, ls='--', lw=0.9)\ndraw_arrow(ax, 5.75, cy - 0.3, k_cx - 0.55, k_bot_y, ls='--', lw=0.9)\n\n# a1 box\ndraw_box(ax, k_cx, k_top_y, 0.9, 0.7, C['coral'], '#D4A0A0', lw=0.8)\nax.text(k_cx, k_top_y, '$a_1$', fontsize=10, ha='center', va='center',\n        color=C['red'], zorder=5)\n\n# a2 box\ndraw_box(ax, k_cx, k_bot_y, 0.9, 0.7, C['green_fill'], '#A0C8A0', lw=0.8)\nax.text(k_cx, k_bot_y, '$a_2$', fontsize=10, ha='center', va='center',\n        color=C['green'], zorder=5)\n\n# K=2 label\nax.text(k_cx + 0.7, cy + 1.55, '$K$=2', fontsize=7.5,\n        color=C['gray_text'], ha='left', va='center', fontfamily='sans-serif', zorder=5)\n\n# 4. Arrows a1,a2 → Argmin\nargmin_cx = 9.4\ndraw_arrow(ax, k_cx + 0.5, k_top_y, argmin_cx - 1.0, cy + 0.15, ls='--', lw=0.9)\ndraw_arrow(ax, k_cx + 0.5, k_bot_y, argmin_cx - 1.0, cy - 0.15, ls='--', lw=0.9)\n\n# Argmin box\ndraw_box(ax, argmin_cx, cy, 1.9, 1.7, C['yellow'], C['yellow_border'])\nax.text(argmin_cx, cy + 0.35, 'Argmin', fontsize=10, fontweight='bold',\n        fontfamily='serif', color='#9A7D0A', ha='center', va='center', zorder=5)\nax.text(argmin_cx, cy - 0.25, r'$\\arg\\min_i \\|a_i\\!-\\!\\bar{a}\\|$',\n        fontsize=7, color=C['gray_text'],\n        ha='center', va='center', zorder=5)\n\n# 5. Arrow Argmin → CRM\ncrm_cx = 12.6\ndraw_arrow(ax, argmin_cx + 1.0, cy, crm_cx - 1.0, cy)\n\n# CRM box\ndraw_box(ax, crm_cx, cy, 1.8, 1.9, C['orange_fill'], C['orange'], lw=1.8)\nax.text(crm_cx, cy + 0.5, 'CRM', fontsize=11, fontweight='bold',\n        fontfamily='serif', color=C['orange'], ha='center', va='center', zorder=5)\nax.text(crm_cx, cy, '615K params', fontsize=6.5, color=C['gray_text'],\n        ha='center', va='center', fontfamily='sans-serif', zorder=5)\nax.text(crm_cx, cy - 0.35, '1.8 MB', fontsize=6.5, color=C['gray_text'],\n        ha='center', va='center', fontfamily='sans-serif', zorder=5)\n\n# 6. Arrow CRM → Refined Action with + δ_a\nref_cx = 15.8\ndraw_arrow(ax, crm_cx + 0.95, cy, ref_cx - 1.0, cy)\nax.text((crm_cx + ref_cx) / 2, cy + 0.35, r'$+\\;\\delta_a$', fontsize=8,\n        color=C['gray_text'], ha='center', va='bottom', zorder=5)\n\n# Refined Action box\ndraw_box(ax, ref_cx, cy, 1.8, 1.4, C['green_fill'], C['green'], lw=1.5)\nax.text(ref_cx, cy + 0.15, 'Refined', fontsize=9, fontfamily='serif',\n        color=C['green'], ha='center', va='center', zorder=5, fontweight='bold')\nax.text(ref_cx, cy - 0.25, 'Action', fontsize=9, fontfamily='serif',\n        color=C['green'], ha='center', va='center', zorder=5, fontweight='bold')\n\n# obs features dashed arc from VLA bottom to CRM bottom\nax.annotate('', xy=(crm_cx, cy - 1.0),\n            xytext=(vla_cx, cy - 1.35),\n            arrowprops=dict(arrowstyle='->,head_width=0.12,head_length=0.2',\n                           color=C['gray_text'], lw=0.8, linestyle='--',\n                           connectionstyle='arc3,rad=0.35'),\n            zorder=2)\nax.text((vla_cx + crm_cx) / 2, cy - 2.3, 'obs features', fontsize=7,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='top', zorder=5)\n\n\n# ══════════════════════════════════════════════════════\n# Panel (b) — Adaptive Gating\n# ══════════════════════════════════════════════════════\nax = ax_b\nax.set_xlim(0, 10)\nax.set_ylim(0, 10)\nax.axis('off')\n\n# Panel label + title\nax.text(0.2, 9.7, '(b)', fontsize=14, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='top')\nax.text(5.0, 9.7, 'Adaptive Gating', fontsize=12, fontweight='bold',\n        fontfamily='serif', color=C['navy'], va='top', ha='center')\n\n# Diamond\nd_cx, d_cy = 5.0, 7.0\nd_r = 1.0\ndiamond = plt.Polygon([\n    (d_cx, d_cy + d_r * 1.1),\n    (d_cx + d_r * 1.4, d_cy),\n    (d_cx, d_cy - d_r * 1.1),\n    (d_cx - d_r * 1.4, d_cy)\n], closed=True, facecolor='#FAFAFA', edgecolor=C['navy'], linewidth=1.5, zorder=3)\nax.add_patch(diamond)\nax.text(d_cx, d_cy + 0.25, 'L2 dist', fontsize=8.5, ha='center', va='center',\n        fontfamily='sans-serif', color=C['navy'], zorder=5, fontweight='bold')\nax.text(d_cx, d_cy - 0.3, r'$d=\\|a_1\\!-\\!a_2\\|_2$', fontsize=7,\n        fontfamily='serif', color=C['gray_text'], ha='center', va='center', zorder=5)\n\n# LEFT branch: d > τ\nl_cx, l_cy = 2.5, 3.0\ndraw_arrow(ax, d_cx - d_r * 1.4 - 0.15, d_cy - 0.5,\n           l_cx + 1.2, l_cy + 1.0, color=C['red'], lw=1.3)\nax.text(d_cx - d_r * 1.4 - 0.5, d_cy + 0.1,\n        r'$d\\!>\\!\\tau$', fontsize=9, fontweight='bold', color=C['red'],\n        ha='center', va='center', zorder=5)\n\ndraw_box(ax, l_cx + 0.5, l_cy + 0.4, 2.8, 1.6, C['coral'], C['red'], lw=1.2)\nax.text(l_cx + 0.5, l_cy + 0.8, 'VLA Uncertain', fontsize=9,\n        fontweight='bold', color=C['red'], ha='center', va='center', zorder=5)\nax.text(l_cx + 0.5, l_cy + 0.15, 'Apply CRM', fontsize=7.5,\n        color=C['gray_text'], ha='center', va='center', zorder=5)\n\n# RIGHT branch: d ≤ τ\nr_cx, r_cy = 7.0, 3.0\ndraw_arrow(ax, d_cx + d_r * 1.4 + 0.15, d_cy - 0.5,\n           r_cx - 0.7, r_cy + 1.0, color=C['green'], lw=1.3)\nax.text(d_cx + d_r * 1.4 + 0.5, d_cy + 0.1,\n        r'$d\\!\\leq\\!\\tau$', fontsize=9, fontweight='bold', color=C['green'],\n        ha='center', va='center', zorder=5)\n\ndraw_box(ax, r_cx + 0.5, r_cy + 0.4, 2.8, 1.6, C['green_fill'], C['green'], lw=1.2)\nax.text(r_cx + 0.5, r_cy + 0.8, 'VLA Confident', fontsize=9,\n        fontweight='bold', color=C['green'], ha='center', va='center', zorder=5)\nax.text(r_cx + 0.5, r_cy + 0.15, 'Use argmin', fontsize=7.5,\n        color=C['gray_text'], ha='center', va='center', zorder=5)\n\n# tau annotation\nax.text(5.0, 1.3, r'$\\tau$ calibrated on held-out demos', fontsize=7,\n        fontstyle='italic', color=C['gray_text'], ha='center', va='center')\n\n\n# ══════════════════════════════════════════════════════\n# Panel (c) — Gating Effect\n# ══════════════════════════════════════════════════════\nax = ax_c\n\nsuites = {\n    'Spatial': (7.8, 2.1, C['navy']),\n    'Goal':    (5.2, 1.3, C['blue']),\n    'Object':  (3.2, 0.1, C['orange']),\n    'Long':    (3.8, -0.3, C['red']),\n}\n\nax.set_xlim(1.5, 9.5)\nax.set_ylim(-1.3, 3.3)\nax.set_facecolor(C['bg'])\n\nfor s in ['top', 'right']:\n    ax.spines[s].set_visible(False)\nfor s in ['left', 'bottom']:\n    ax.spines[s].set_color(C['spine'])\n    ax.spines[s].set_linewidth(0.8)\n\nax.yaxis.grid(True, color=C['grid'], linewidth=0.5, zorder=0)\nax.xaxis.grid(False)\nax.set_xticks([2, 3, 4, 5, 6, 7, 8, 9])\nax.set_yticks([-1.0, 0.0, 1.0, 2.0, 3.0])\nax.tick_params(axis='both', labelsize=7, colors=C['gray_text'], length=3, width=0.6)\n\nax.set_xlabel('Trigger Rate (%)', fontsize=8.5, fontfamily='serif', color=C['navy'], labelpad=4)\nax.set_ylabel('Δ SR (pp)', fontsize=8.5, fontfamily='serif', color=C['navy'], labelpad=4)\n\n# Title\nax.text(0.5, 1.04, 'Gating Modulates Intervention', fontsize=10, fontweight='bold',\n        fontfamily='serif', color=C['navy'], ha='center', va='bottom',\n        transform=ax.transAxes)\nax.text(-0.12, 1.04, '(c)', fontsize=14, fontweight='bold', fontfamily='serif',\n        color=C['navy'], va='bottom', transform=ax.transAxes)\n\n# Vertical dashed line at x=5\nax.axvline(x=5.0, color=C['spine'], linewidth=0.8, linestyle='--', zorder=1, alpha=0.6)\nax.text(3.3, 3.1, 'Confident', fontsize=7, fontstyle='italic', color=C['gray_text'],\n        ha='center', va='bottom')\nax.text(7.2, 3.1, 'Uncertain', fontsize=7, fontstyle='italic', color=C['gray_text'],\n        ha='center', va='bottom')\n\n# Zero line\nax.axhline(y=0, color=C['spine'], linewidth=0.4, zorder=1, alpha=0.4)\n\n# Data points\noffsets = {\n    'Spatial': (0.4, 0.0),\n    'Goal':    (0.4, 0.05),\n    'Object':  (-0.2, 0.3),\n    'Long':    (-0.15, -0.35),\n}\n\nfor name, (x, y, color) in suites.items():\n    ax.scatter(x, y, s=160, facecolor='white', edgecolor=color, linewidth=2.2, zorder=5)\n    ox, oy = offsets[name]\n    ax.text(x + ox, y + oy, name, fontsize=7.5, color=color, fontweight='bold',\n            va='center', ha='left' if ox > 0 else 'right', zorder=5)\n\n# ── Save ──\nout = '/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/artifacts/figures/fig1_vA_dense'\nplt.savefig(f'{out}.png', dpi=300, bbox_inches='tight', pad_inches=0.05, facecolor=C['bg'])\nplt.savefig(f'{out}.pdf', bbox_inches='tight', pad_inches=0.05, facecolor=C['bg'])\nplt.close()\nprint('PNG + PDF saved')\n","userModified":false}}
